package tw.sungo.controller;
import tw.sungo.model.*;import tw.sungo.repo.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import java.nio.file.*;import java.io.IOException;
@RestController @RequestMapping("/api/admin") public class AdminController {
 private final ProductRepository products;private final NewsRepository news;private final InquiryRepository inquiries;private final SettingRepository settings;private final Path uploadPath;
 public AdminController(ProductRepository p,NewsRepository n,InquiryRepository i,SettingRepository s,@org.springframework.beans.factory.annotation.Value("${app.upload-dir}") String dir){products=p;news=n;inquiries=i;settings=s;uploadPath=Path.of(dir).toAbsolutePath().normalize();}
 public record ProductInput(@NotBlank String name,@NotBlank String category,String description,String imageUrl,String code,boolean published,int sortOrder){}
 public record NewsInput(@NotBlank String title,String summary,String content,String imageUrl,java.time.LocalDate publishedDate,boolean published){}
 @GetMapping("/products") public List<Product> allProducts(){return products.findAllByOrderBySortOrderAscIdDesc();}
 @PostMapping("/products") @ResponseStatus(HttpStatus.CREATED) public Product createProduct(@Valid @RequestBody ProductInput r){Product p=new Product();apply(p,r);return products.save(p);}
 @PutMapping("/products/{id}") public Product updateProduct(@PathVariable Long id,@Valid @RequestBody ProductInput r){Product p=products.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));apply(p,r);return products.save(p);}
 private void apply(Product p,ProductInput r){p.setName(r.name());p.setCategory(r.category());p.setDescription(r.description());p.setImageUrl(r.imageUrl());p.setCode(r.code());p.setPublished(r.published());p.setSortOrder(r.sortOrder());}
 @DeleteMapping("/products/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteProduct(@PathVariable Long id){products.deleteById(id);}
 @GetMapping("/news") public List<NewsArticle> allNews(){return news.findAllByOrderByPublishedDateDescIdDesc();}
 @PostMapping("/news") @ResponseStatus(HttpStatus.CREATED) public NewsArticle createNews(@Valid @RequestBody NewsInput r){NewsArticle n=new NewsArticle();apply(n,r);return news.save(n);}
 @PutMapping("/news/{id}") public NewsArticle updateNews(@PathVariable Long id,@Valid @RequestBody NewsInput r){NewsArticle n=news.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));apply(n,r);return news.save(n);}
 private void apply(NewsArticle n,NewsInput r){n.setTitle(r.title());n.setSummary(r.summary());n.setContent(r.content());n.setImageUrl(r.imageUrl());n.setPublishedDate(r.publishedDate()==null?java.time.LocalDate.now():r.publishedDate());n.setPublished(r.published());}
 @DeleteMapping("/news/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteNews(@PathVariable Long id){news.deleteById(id);}
 @GetMapping("/inquiries") public List<Inquiry> allInquiries(){return inquiries.findAll(org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"createdAt"));}
 @PatchMapping("/inquiries/{id}/status") public Inquiry status(@PathVariable Long id,@RequestBody Map<String,String> body){Inquiry i=inquiries.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));String s=body.getOrDefault("status","NEW");if(!List.of("NEW","IN_PROGRESS","CLOSED").contains(s))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid status");i.setStatus(s);return inquiries.save(i);}
 @GetMapping("/settings") public Map<String,String> allSettings(){Map<String,String> m=new TreeMap<>();settings.findAll().forEach(s->m.put(s.getSettingKey(),s.getSettingValue()));return m;}
 @PutMapping("/settings") public Map<String,String> updateSettings(@RequestBody Map<String,String> values){values.forEach((k,v)->{if(k!=null&&k.matches("[a-zA-Z][a-zA-Z0-9]{0,60}")&&v!=null){SiteSetting s=settings.findById(k).orElseGet(()->new SiteSetting(k,""));s.setSettingValue(v);settings.save(s);}});return allSettings();}
 @PostMapping("/uploads") public Map<String,String> upload(@RequestParam("file") MultipartFile file)throws IOException{if(file.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Empty file");String type=file.getContentType()==null?"":file.getContentType();if(!List.of("image/jpeg","image/png","image/webp","image/gif").contains(type))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only JPEG, PNG, WEBP and GIF images are allowed");if(file.getSize()>8*1024*1024)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Image must be 8 MB or smaller");Files.createDirectories(uploadPath);String ext=switch(type){case "image/jpeg"->"jpg";case "image/png"->"png";case "image/webp"->"webp";default->"gif";};String name=UUID.randomUUID()+"."+ext;Path target=uploadPath.resolve(name).normalize();if(!target.startsWith(uploadPath))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);Files.copy(file.getInputStream(),target,StandardCopyOption.REPLACE_EXISTING);return Map.of("url","/uploads/"+name);}
}
